use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;

struct Node;

/// Builds the enrichment URL for one input: the date and the considered ids,
/// percent-encoded into the `q` query parameter.
fn enrich_url(published: &PublishedDigest) -> String {
    let mut text = String::new();
    text.push_str(&published.date);
    for id in published.considered.iter() {
        text.push(',');
        text.push_str(id);
    }

    let mut q = String::with_capacity(text.len() * 3);
    for b in text.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                q.push(b as char)
            }
            _ => q.push_str(&format!("%{:02X}", b)),
        }
    }

    format!("https://metadata.internal.example/enrich?q={}", q)
}

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Enrichment is fire-and-forget: its result never affects the output.
        // `fetch` reports transport failures as values, so a down host is harmless.
        let _ = http_client::fetch(&enrich_url(&published));

        let mut recorded: u32 = 0;

        if published.published {
            for id in published.considered.iter() {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
